import openpyxl
from openpyxl.utils import get_column_letter

in_path='/root/data/workbook.xlsx'
out_path='/root/output/result.xlsx'

wb=openpyxl.load_workbook(in_path, data_only=False)
ws_task=wb['Task']

# Data sheet ranges based on inspection
DATA_VAL_RANGE='Data!$H$21:$L$38'
DATA_SERIES_RANGE='Data!$D$21:$D$38'
DATA_YEAR_RANGE='Data!$H$4:$L$4'

# Helper to set INDEX/MATCH formula at given task cell

def set_index_match(row:int, col_letter:str):
    # task year headers are in row 10, so year cell is like H$10
    formula=(
        f"=INDEX({DATA_VAL_RANGE},"
        f" MATCH($D{row}, {DATA_SERIES_RANGE}, 0),"
        f" MATCH({col_letter}$10, {DATA_YEAR_RANGE}, 0))"
    )
    ws_task[f'{col_letter}{row}'].value=formula

# Fill blocks
for r in range(12,18):
    for col in 'HIJKL':
        set_index_match(r,col)

for r in range(19,25):
    for col in 'HIJKL':
        set_index_match(r,col)

for r in range(26,32):
    for col in 'HIJKL':
        set_index_match(r,col)

# Step 2 formulas: headroom rows 35-40
# Map cluster index i=0..5 -> avail row 12+i, occup row 19+i, staffed row 26+i, headroom row 35+i
for i in range(6):
    avail=12+i
    occup=19+i
    staffed=26+i
    head=35+i
    for col in 'HIJKL':
        ws_task[f'{col}{head}'].value=f"=({col}{avail}-{col}{occup})/{col}{staffed}*100"

# Summary statistics rows 42-47; verify labels and assign accordingly
label_to_row={
    'Minimum':42,
    'Maximum':43,
    'Median':44,
    'Simple mean':45,
    '25th percentile':46,
    '75th percentile':47,
}
# read actual labels in Task!E42:E47
actual_labels={ws_task[f'E{r}'].value:r for r in range(42,48)}
# Build mapping row->stat based on labels
row_stat={}
for label,row in label_to_row.items():
    # find row containing this label
    found_row=None
    for r in range(42,48):
        if ws_task[f'E{r}'].value==label:
            found_row=r
            break
    if found_row is None:
        raise RuntimeError(f"Expected label '{label}' not found in E42:E47")
    row_stat[found_row]=label

for col in 'HIJKL':
    rng=f"{col}35:{col}40"
    for r in range(42,48):
        label=row_stat[r]
        if label=='Minimum':
            ws_task[f'{col}{r}'].value=f"=MIN({rng})"
        elif label=='Maximum':
            ws_task[f'{col}{r}'].value=f"=MAX({rng})"
        elif label=='Median':
            ws_task[f'{col}{r}'].value=f"=MEDIAN({rng})"
        elif label=='Simple mean':
            ws_task[f'{col}{r}'].value=f"=AVERAGE({rng})"
        elif label=='25th percentile':
            ws_task[f'{col}{r}'].value=f"=PERCENTILE({rng},0.25)"
        elif label=='75th percentile':
            ws_task[f'{col}{r}'].value=f"=PERCENTILE({rng},0.75)"

# Weighted mean row 50
for col in 'HIJKL':
    ws_task[f'{col}50'].value=f"=SUMPRODUCT({col}35:{col}40,{col}26:{col}31)/SUM({col}26:{col}31)"

wb.save(out_path)
print('Saved', out_path)
